This Terraform configuration creates an AWS S3 bucket named `mybucket` in the `us-east-1` region. It then uploads a local file from `path/to/file` into that bucket as an S3 object.

```hcl
terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "mybucket" {
  bucket = "mybucket"
}

resource "aws_s3_object" "uploaded_file" {
  bucket = aws_s3_bucket.mybucket.id
  key    = "file"
  source = "path/to/file"

  etag = filemd5("path/to/file")
}
```
